                               <NeoSparkles className="w-14 h-14 text-earth-900" />
                           </div>
                           <div className="absolute -bottom-2 -right-2 bg-white p-2 rounded-full shadow-md border border-earth-50">
                               <NeoStar className="w-6 h-6 text-pop-purple" />
                           </div>
                      </div>
                      <h2 className="font-display font-black text-3xl text-earth-900 mb-2 leading-tight text-center">
                          Challenges &<br/>Rewards
                      </h2>
                      <p className="text-earth-500 font-medium text-base mb-8 max-w-[240px] leading-relaxed text-center">
                          We’re building fun rewards for our early community.
                      </p>
                      <div className="mb-8 inline-flex items-center gap-2 px-4 py-2 bg-earth-900 rounded-xl shadow-lg shadow-earth-900/10">
                          <Sparkles className="w-3 h-3 text-pop-lime animate-pulse" />
                          <span className="text-[10px] font-black text-white uppercase tracking-widest">Coming Soon</span>
                      </div>
                      <p className="text-xs text-earth-400 font-bold text-center">
                          Use Revendre. Something special unlocks soon.
                      </p>
                  </div>
              </div>
          );
      case Tab.ACTIVITY_VIEW:
          return (
              <div className="px-6 py-6">
                  <div className="flex items-center justify-between mb-6">
                     <h2 className="font-display font-black text-2xl">Updates</h2>
                     <button onClick={() => setActiveTab(Tab.QNA_INBOX)} className="flex items-center gap-2 bg-earth-100 text-earth-900 px-4 py-2 rounded-xl text-xs font-bold hover:bg-earth-200 transition-colors">
                         <MessageSquare className="w-4 h-4"/> Q&A Inbox
                     </button>
                  </div>
                  <div className="bg-white p-5 rounded-[2rem] shadow-md flex gap-4 animate-fade-in-up">
                      <div className="w-12 h-12 rounded-full bg-pop-lime/20 flex items-center justify-center text-pop-lime shrink-0">
                          <ShieldCheck className="w-6 h-6" />
                      </div>
                      <div>
                          <h4 className="font-bold text-earth-900 text-sm">Order Processed</h4>
                          <p className="text-xs text-earth-500 mt-1 font-medium">Your 'Vintage Levis' has passed the Hub check and is verified for delivery.</p>
                      </div>
                  </div>
              </div>
          )
      case Tab.PROFILE:
        return (
            <div className="relative">
                 <button onClick={handleLogout} className="absolute top-6 left-6 z-20 bg-white/20 backdrop-blur p-2 rounded-full hover:bg-white/40 text-white transition-colors"><LogOut className="w-5 h-5"/></button>
                 <Profile 
                    user={user!} 
                    posts={posts} 
                    savedPosts={savedPostsList}
                    onOpenDashboard={() => setActiveTab(Tab.SELLER_DASHBOARD)} 
                    onOpenOrderTracking={() => setActiveTab(Tab.ORDER_TRACKING)}
                    onOpenSettings={() => setIsSettingsOpen(true)}
                    onPostClick={setViewingPost}
                 />
            </div>
        );
      default:
        return null;
    }
  };

  const isModalOpen = isUploadOpen || isAiChatOpen || isSettingsOpen || isFilterOpen || isPaymentOpen || isAddressOpen || !!viewingPost;

  return (
    <Layout 
      activeTab={activeTab} 
      onTabChange={handleTabChange} 
      onOpenUpload={() => setIsUploadOpen(true)} 
      cartCount={cart.length}
      hideNav={isModalOpen}
    >
      {renderTabContent()}
      {viewingPost && (
          <ProductDetail 
            post={viewingPost}
            onClose={() => setViewingPost(null)}
            onAddToCart={handleAddToCart}
            onBuyNow={(p) => {
                handleAddToCart(p);
                setActiveTab(Tab.CART);
                setViewingPost(null);
            }}
            onMakeOffer={(p) => {
                setViewingPost(null);
                setActiveOfferPost(p);
            }}
            isSaved={savedPostIds.includes(viewingPost.id)}
            onToggleSave={handleToggleSave}
          />
      )}
      <UploadModal isOpen={isUploadOpen} onClose={() => setIsUploadOpen(false)} onPost={handlePost} />
      <AskModal isOpen={!!activeAskPost} onClose={() => setActiveAskPost(null)} post={activeAskPost} onSubmit={handleAskQuestion} />
      {activeOfferPost && (
          <OfferModal 
            isOpen={!!activeOfferPost} 
            onClose={() => setActiveOfferPost(null)} 
            post={activeOfferPost} 
            onSubmit={handleMakeOffer} 
          />
      )}
      {user && (
          <ProfileSettingsModal 
            isOpen={isSettingsOpen} 
            onClose={() => setIsSettingsOpen(false)} 
            currentUser={user} 
            onUpdateUser={handleUpdateProfile} 
          />
      )}
      <FilterModal 
        isOpen={isFilterOpen}
        onClose={() => setIsFilterOpen(false)}
        availableSizes={availableSizes}
        availableBrands={availableBrands}
        availableCategories={ITEM_TYPES}
        availableColors={availableColors}
        currentFilters={filters}
        onApply={setFilters}
      />
      <CheckoutAddressModal
        isOpen={isAddressOpen}
        onClose={() => setIsAddressOpen(false)}
        existingAddresses={user?.addresses || []}
        onConfirm={handleAddressConfirmed}
      />
      <PaymentModal 
        isOpen={isPaymentOpen}
        onClose={() => setIsPaymentOpen(false)}
        totalAmount={pendingPaymentOrder ? (pendingPaymentOrder.totalAmount || 0) : cart.reduce((sum, item) => sum + item.price, 0)}
        onComplete={handlePaymentComplete}
      />
      {!isModalOpen && activeTab !== Tab.CHALLENGES && (
        <button
            onClick={() => setIsAiChatOpen(true)}
            className="fixed bottom-28 right-4 z-40 w-12 h-12 bg-earth-900 text-white rounded-full shadow-xl flex items-center justify-center border-2 border-white hover:scale-110 transition-transform active:scale-95 animate-bounce-in"
        >
            <NeoBot className="w-6 h-6" />
        </button>
      )}
      <AiChatModal isOpen={isAiChatOpen} onClose={() => setIsAiChatOpen(false)} />
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Button } from './Button';
import { ArrowRight, Droplets, Truck, Users, CheckCircle2, AlertCircle, MapPin, Briefcase, Home, Loader2, User, Phone, Map, ShieldCheck } from 'lucide-react'; 
import { NeoSparkles, NeoCamera } from './NeoIcons';
import { Address } from '../types';

interface OnboardingProps {
  onComplete: (data: any) => void;
}

// Mock taken usernames for demo
const TAKEN_USERNAMES = ['admin', 'revendre', 'test', 'user', 'support', 'thrift_king'];

// Mock Pincode Data
const MOCK_PINCODES: Record<string, { city: string, state: string }> = {
    '40': { city: 'Mumbai', state: 'Maharashtra' },
    '11': { city: 'New Delhi', state: 'Delhi' },
    '56': { city: 'Bengaluru', state: 'Karnataka' },
    '60': { city: 'Chennai', state: 'Tamil Nadu' },
    '70': { city: 'Kolkata', state: 'West Bengal' },
    '50': { city: 'Hyderabad', state: 'Telangana' },
    '38': { city: 'Ahmedabad', state: 'Gujarat' },
    '30': { city: 'Jaipur', state: 'Rajasthan' },
    '41': { city: 'Pune', state: 'Maharashtra' }, 
    '20': { city: 'Noida', state: 'Uttar Pradesh' }, 
};

export const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [slideIndex, setSlideIndex] = useState(0);

  // Setup Steps: 0 = Intro Slides, 1 = Profile Basics, 2 = Address
  const [setupStep, setSetupStep] = useState(0);

  // Profile State
  const [username, setUsername] = useState('');
  const [gender, setGender] = useState<string>(''); // Added Gender state
  const [usernameStatus, setUsernameStatus] = useState<'idle' | 'checking' | 'available' | 'taken' | 'invalid'>('idle');
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [avatarUrl, setAvatarUrl] = useState<string>('');
  const [avatarFile, setAvatarFile] = useState<File | null>(null);

  const checkTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Address State
  const [address, setAddress] = useState({
    fullName: '',
    mobile: '',
    line1: '',
    line2: '',
    landmark: '',
    pincode: '',
    city: '',
    state: '',
    type: 'Home' as 'Home' | 'Work' | 'Other'
  });

  const [isPincodeLoading, setIsPincodeLoading] = useState(false);

  // Set default avatar based on username if not set
  useEffect(() => {
    if (!avatarFile) {
        const seed = username || 'User';
        setAvatarUrl(`https://ui-avatars.com/api/?background=E7E5E4&color=1C1917&name=${seed}&size=200&bold=true`);
    }
  }, [username, avatarFile]);

  const slides = [
    {
      id: 1,
      title: "The Revendre\nCommunity",
      desc: "Welcome to the fam! We are India's #1 social thrift marketplace. Buy, sell, and discover pre-loved fashion.",
      color: "bg-pop-yellow",
      image: "https://images.unsplash.com/photo-1523381210434-271e8be1f52b?auto=format&fit=crop&q=80&w=600",
      icon: <NeoSparkles className="w-10 h-10" />
    },
    {
      id: 2,
      title: "The Green\nRevolution",
      desc: "Every reused outfit saves water, energy, and reduces textile waste. Support a greener future.",
      color: "bg-pop-lime",
      image: "https://images.unsplash.com/photo-1542601906990-b4d3fb778b09?auto=format&fit=crop&q=80&w=600",
      icon: <Droplets className="w-10 h-10 text-earth-900" strokeWidth={2.5} />
    },
    {
      id: 3,
      title: "Creating\nLivelihoods",
      desc: "Revendre helps create jobs and steady income for small local businesses and delivery partners.",
      color: "bg-pop-cyan",
      image: "https://images.unsplash.com/photo-1556740758-90de374c12ad?auto=format&fit=crop&q=80&w=600",
      icon: <div className="flex gap-1.5"><Users className="w-6 h-6 text-earth-900"/><Truck className="w-6 h-6 text-earth-900"/></div>
    }
  ];

  const handleNextSlide = () => {
    if (slideIndex < slides.length - 1) {
      setSlideIndex(slideIndex + 1);
    } else {
      setSetupStep(1); 
    }
  };

  const handleSkip = () => {
    setSetupStep(1); 
  };

  const handleUsernameChange = (val: string) => {
    const cleanVal = val.toLowerCase().replace(/[^a-z0-9_]/g, '');
    setUsername(cleanVal);

    if (checkTimeoutRef.current) clearTimeout(checkTimeoutRef.current);

    if (cleanVal.length < 3) {
      setUsernameStatus(cleanVal.length === 0 ? 'idle' : 'invalid');
      setSuggestions([]);
      return;
    }

    setUsernameStatus('checking');

    checkTimeoutRef.current = setTimeout(() => {
      if (TAKEN_USERNAMES.includes(cleanVal)) {
        setUsernameStatus('taken');
        setSuggestions([
            `${cleanVal}_thrifter`,
            `real_${cleanVal}`,
            `${cleanVal}${Math.floor(Math.random() * 99)}`
        ]);
      } else {
        setUsernameStatus('available');
        setSuggestions([]);
      }
    }, 200); 
  };

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setAvatarFile(file);
      setAvatarUrl(URL.createObjectURL(file));
    }
  };

  const handleProfileSubmit = () => {
    if (usernameStatus !== 'available' || !gender) return;
    setSetupStep(2); 
  };

  const handlePincodeChange = (code: string) => {
      setAddress(prev => ({ ...prev, pincode: code }));

      if (code.length === 6) {
          setIsPincodeLoading(true);
          setTimeout(() => {
              const prefix = code.substring(0, 2);
              const data = MOCK_PINCODES[prefix];
              if (data) {
                  setAddress(prev => ({ ...prev, city: data.city, state: data.state }));
              }
              setIsPincodeLoading(false);
          }, 300); 
      }
  };

  const handleAddressChange = (field: string, value: string) => {
    setAddress(prev => ({ ...prev, [field]: value }));
  };

  const handleFinalSubmit = () => {
    if (!address.fullName || address.mobile.length !== 10 || !address.line1 || address.pincode.length !== 6 || !address.city) return;

    const finalAddress: Address = {
        id: `addr-${Date.now()}`,
        ...address,
        isDefault: true
    };

    const userData = {
        username,
        gender,
        displayName: address.fullName || username,
        avatarUrl, 
        addresses: [finalAddress],
        city: address.city
    };

    onComplete(userData);
  };

  const handleSkipAddress = () => {
    const userData = {
        username,
        gender,
        displayName: username,
        avatarUrl, 
        addresses: [],
        city: ''
    };
    onComplete(userData);
  };

  if (setupStep === 1) {
      return (
          <div className="min-h-screen bg-[#FAFAF9] flex flex-col items-center justify-center p-6 animate-fade-in-up">
              <div className="w-full max-w-md bg-white rounded-[2.5rem] shadow-xl p-8 border border-earth-100 relative overflow-hidden">
                  <div className="absolute top-0 right-0 w-32 h-32 bg-pop-yellow/20 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none"></div>

                  <div className="relative z-10">
                      <div className="text-center mb-8">
                          <h2 className="font-display font-black text-3xl text-earth-900 mb-2">Create Profile ✨</h2>
                          <p className="text-earth-500 text-sm font-medium">Let's get you set up.</p>
                      </div>

                      <div className="flex flex-col items-center mb-8">
                          <div className="relative group cursor-pointer">
                              <div className="w-32 h-32 rounded-full border-4 border-white shadow-xl overflow-hidden bg-earth-100 relative z-10">
                                  <img src={avatarUrl} className="w-full h-full object-cover" alt="Profile" decoding="async" />
                              </div>
                              <label className="absolute inset-0 bg-black/40 rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer z-20">
                                  <NeoCamera className="w-8 h-8 text-white" />
                                  <input type="file" className="hidden" accept="image/*" onChange={handleImageSelect} />
                              </label>
                              <div className="absolute bottom-1 right-1 bg-earth-900 p-2.5 rounded-full border-4 border-white shadow-md pointer-events-none z-30">
                                  <NeoCamera className="w-4 h-4 text-white" />
                              </div>
                          </div>
                          <p className="text-[10px] text-earth-400 font-bold uppercase tracking-wide mt-3">Upload Picture (Optional)</p>
                      </div>

                      <div className="space-y-6 mb-8">
                          <div>
                              <label className="block text-xs font-bold text-earth-900 uppercase tracking-wide mb-1 ml-1">Username <span className="text-pop-rose">*</span></label>
                              <div className={`relative flex items-center bg-earth-50 border-2 rounded-2xl transition-all ${
                                  usernameStatus === 'taken' ? 'border-pop-rose' : 
                                  usernameStatus === 'available' ? 'border-pop-lime' : 
                                  'border-transparent focus-within:border-earth-900 focus-within:bg-white'
                              }`}>
                                  <span className="pl-4 text-earth-400 font-bold text-lg">@</span>
                                  <input 
                                      value={username}
                                      onChange={(e) => handleUsernameChange(e.target.value)}
                                      className="w-full bg-transparent py-4 pl-1 pr-12 font-bold text-lg text-earth-900 outline-none placeholder:text-earth-300"
                                      placeholder="thrift_king"
                                      autoFocus
                                  />
                                  <div className="absolute right-4">
                                      {usernameStatus === 'checking' && <Loader2 className="w-5 h-5 text-earth-400 animate-spin" />}
                                      {usernameStatus === 'available' && <CheckCircle2 className="w-6 h-6 text-pop-lime fill-earth-50" />}
                                      {usernameStatus === 'taken' && <AlertCircle className="w-6 h-6 text-pop-rose fill-earth-50" />}
                                  </div>
                              </div>

                              {usernameStatus === 'taken' && (
                                  <div className="mt-3 animate-slide-up bg-pop-rose/5 p-3 rounded-xl border border-pop-rose/10">
                                      <p className="text-xs text-pop-rose font-bold mb-2">Username taken. Try these:</p>
                                      <div className="flex flex-wrap gap-2">
                                          {suggestions.map(s => (
                                              <button 
                                                key={s} 
                                                onClick={() => handleUsernameChange(s)}
                                                className="text-[10px] bg-white border border-pop-rose/20 px-3 py-1.5 rounded-lg font-bold text-pop-rose hover:bg-pop-rose hover:text-white transition-colors shadow-sm"
                                              >
                                                  @{s}
                                              </button>
                                          ))}
                                      </div>
                                  </div>
                              )}
                          </div>

                          {/* Added Gender Selection grid */}
                          <div>
                              <label className="block text-xs font-bold text-earth-900 uppercase tracking-wide mb-2 ml-1">Gender <span className="text-pop-rose">*</span></label>
                              <div className="grid grid-cols-2 gap-3">
                                  {['Men', 'Women', 'Non-binary', 'Not interested'].map((opt) => (
                                      <button
                                          key={opt}
                                          onClick={() => setGender(opt)}
                                          className={`py-3.5 px-4 rounded-2xl text-sm font-bold transition-all border-2 flex items-center justify-center ${
                                              gender === opt 
                                              ? 'bg-earth-900 text-white border-earth-900 shadow-lg scale-[1.02]' 
                                              : 'bg-white text-earth-500 border-earth-100 hover:border-earth-200 active:scale-95'
                                          }`}
                                      >
                                          {opt}
                                      </button>
                                  ))}
                              </div>
                          </div>
                      </div>

                      <Button 
                        onClick={handleProfileSubmit} 
                        className="w-full py-3 text-base shadow-lg"
                        disabled={usernameStatus !== 'available' || !gender}
                      >
                          Next: Address <ArrowRight className="w-5 h-5 ml-2"/>
                      </Button>
                  </div>
              </div>
          </div>
      );
  }

  if (setupStep === 2) {
      return (
          <div className="min-h-screen bg-[#FAFAF9] flex flex-col items-center justify-center p-6 animate-slide-in-right">
              <div className="w-full max-w-md bg-white rounded-[2.5rem] shadow-xl p-8 border border-earth-100 relative overflow-hidden flex flex-col max-h-[90vh]">

                  <div className="relative z-10 flex flex-col h-full overflow-hidden">
                      <div className="mb-6 shrink-0">
                          <h2 className="font-display font-black text-3xl text-earth-900 mb-1">Shipping Details 📦</h2>
                          <p className="text-earth-700 text-sm font-bold mb-3">Where should we send your finds?</p>

                          <div className="inline-flex items-center gap-1.5 bg-earth-50 border border-earth-100 px-2 py-1.5 rounded-lg">
                              <ShieldCheck className="w-3 h-3 text-earth-700" />
                              <span className="text-[10px] font-black text-earth-700 uppercase tracking-wide">Used only for pickups & deliveries</span>
                          </div>
                      </div>

                      <div className="space-y-6 overflow-y-auto pr-2 pb-4 flex-1 no-scrollbar">

                          <div className="space-y-3">
                              <h4 className="text-xs font-black text-earth-900 uppercase tracking-widest mb-2 flex items-center gap-2"><User className="w-3 h-3"/> Contact</h4>
                              <div className="bg-earth-50 p-1 rounded-2xl border border-earth-100">
                                  <div className="relative border-b border-earth-100">
                                      <User className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-earth-600" />
                                      <input 
                                          value={address.fullName}
                                          onChange={(e) => handleAddressChange('fullName', e.target.value)}
                                          className="w-full bg-transparent pl-12 pr-4 py-4 font-bold text-sm text-earth-900 outline-none placeholder:text-earth-400 placeholder:font-medium"
                                          placeholder="Full Name"
                                      />
                                  </div>
                                  <div className="relative">
                                      <Phone className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-earth-600" />
                                      <input 
                                          value={address.mobile}
                                          onChange={(e) => handleAddressChange('mobile', e.target.value.replace(/\D/g, '').slice(0, 10))}
                                          className="w-full bg-transparent pl-12 pr-4 py-4 font-bold text-sm text-earth-900 outline-none placeholder:text-earth-400 placeholder:font-medium"
                                          placeholder="Mobile Number"
                                          type="tel"
                                          maxLength={10}
                                      />
                                      {address.mobile.length === 10 && (
                                          <CheckCircle2 className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-pop-lime" />
                                      )}
                                  </div>
                              </div>
                          </div>

                          <div className="space-y-3">
                              <h4 className="text-xs font-black text-earth-900 uppercase tracking-widest mb-2 flex items-center gap-2"><MapPin className="w-3 h-3"/> Location</h4>

                              <div className="grid grid-cols-2 gap-3">
                                  <div className="bg-earth-50 rounded-2xl px-4 py-3 border border-earth-100 relative">
                                      <label className="text-[10px] font-black text-earth-800 uppercase tracking-wide block mb-1">Pincode</label>
                                      <input 
                                          value={address.pincode}
                                          onChange={(e) => handlePincodeChange(e.target.value.replace(/\D/g, '').slice(0, 6))}
                                          className="w-full bg-transparent font-bold text-earth-900 outline-none placeholder:text-earth-400"
                                          placeholder="000000"
                                          type="tel"
                                          maxLength={6}
                                      />
                                      {isPincodeLoading && <Loader2 className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 animate-spin text-earth-600"/>}
                                  </div>
                                  <div className="bg-earth-50 rounded-2xl px-4 py-3 border border-earth-100">
                                      <label className="text-[10px] font-black text-earth-800 uppercase tracking-wide block mb-1">City</label>
                                      <input 
                                          value={address.city}
                                          onChange={(e) => handleAddressChange('city', e.target.value)}
                                          className="w-full bg-transparent font-bold text-earth-900 outline-none placeholder:text-earth-400"
                                          placeholder="City"
                                      />
                                  </div>
                              </div>

                              <div className="bg-earth-50 p-4 rounded-2xl border border-earth-100 space-y-4">
                                  <input 
                                      value={address.line1}
                                      onChange={(e) => handleAddressChange('line1', e.target.value)}
                                      className="w-full bg-transparent border-b border-earth-300 pb-2 font-bold text-sm text-earth-900 outline-none placeholder:text-earth-400 focus:border-earth-600 transition-colors"
                                      placeholder="Flat, House no., Building, Apartment"
                                  />
                                  <input 
                                      value={address.line2}
                                      onChange={(e) => handleAddressChange('line2', e.target.value)}
                                      className="w-full bg-transparent border-b border-earth-300 pb-2 font-bold text-sm text-earth-900 outline-none placeholder:text-earth-400 focus:border-earth-600 transition-colors"
                                      placeholder="Area, Street, Sector, Village"
                                  />
                                  <div className="grid grid-cols-2 gap-4">
                                      <input 
                                          value={address.landmark}
                                          onChange={(e) => handleAddressChange('landmark', e.target.value)}
                                          className="w-full bg-transparent font-bold text-sm text-earth-900 outline-none placeholder:text-earth-400"
                                          placeholder="Landmark"
                                      />
                                      <input 
                                          value={address.state}
                                          onChange={(e) => handleAddressChange('state', e.target.value)}
                                          className="w-full bg-transparent font-bold text-sm text-earth-900 outline-none placeholder:text-earth-400 text-right"
                                          placeholder="State"
                                      />
                                  </div>
                              </div>
                          </div>

                          <div>
                              <h4 className="text-xs font-black text-earth-900 uppercase tracking-widest mb-2 flex items-center gap-2"><Map className="w-3 h-3"/> Save As</h4>
                              <div className="bg-earth-50 p-1 rounded-xl flex gap-1">
                                  {[
                                      { id: 'Home', icon: Home }, 
                                      { id: 'Work', icon: Briefcase }, 
                                      { id: 'Other', icon: MapPin }
                                  ].map((t) => (
                                      <button
                                          key={t.id}
                                          onClick={() => handleAddressChange('type', t.id)}
                                          className={`flex-1 py-2 rounded-lg text-xs font-bold transition-all flex items-center justify-center gap-2 ${
                                              address.type === t.id 
                                              ? 'bg-white text-earth-900 shadow-sm border border-earth-100' 
                                              : 'text-earth-600 hover:text-earth-800'
                                          }`}
                                      >
                                          <t.icon className="w-3.5 h-3.5" /> {t.id}
                                      </button>
                                  ))}
                              </div>
                          </div>
                      </div>

                      <div className="mt-4 pt-4 border-t border-earth-100 shrink-0 flex flex-col gap-3">
                           <Button 
                              onClick={handleFinalSubmit} 
                              className="w-full py-3 text-base shadow-lg"
                              disabled={!address.fullName || address.mobile.length < 10 || !address.line1 || address.pincode.length < 6 || !address.city}
                            >
                              Complete Setup <CheckCircle2 className="w-5 h-5 ml-2"/>
                           </Button>
                           <button 
                              onClick={handleSkipAddress}
                              className="text-xs font-bold text-earth-500 uppercase tracking-wide hover:text-earth-700 transition-colors py-2"
                           >
                              Skip for now
                           </button>
                      </div>
                  </div>
              </div>
          </div>
      );
  }

  const currentSlide = slides[slideIndex];

  return (
      <div className="min-h-screen bg-[#FAFAF9] flex flex-col items-center justify-center p-6 relative">
          <button 
            onClick={handleSkip} 
            className="absolute top-6 right-6 text-earth-500 text-sm font-bold uppercase tracking-wide hover:text-earth-900 z-50 px-4 py-2"
          >
            Skip Intro
          </button>

          <div className="w-full max-w-sm flex flex-col h-[85vh]">
              <div className={`flex-1 rounded-[3rem] ${currentSlide.color} mb-8 overflow-hidden shadow-2xl relative group animate-pop`} key={slideIndex}>
                  <img 
                    src={currentSlide.image} 
                    className="w-full h-full object-cover mix-blend-multiply opacity-80 transition-transform duration-700 group-hover:scale-110" 
                    alt="Slide visual"
                    decoding="async"
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/50 via-transparent to-transparent"></div>

                  <div className="absolute top-6 right-6 w-16 h-16 bg-white rounded-full flex items-center justify-center shadow-lg animate-bounce-in overflow-hidden">
                      {currentSlide.icon}
                  </div>

                  <div className="absolute bottom-8 left-8 right-8">
                      <h2 className="text-white font-display font-black text-4xl leading-[0.9] drop-shadow-md whitespace-pre-line mb-2 animate-slide-up">
                        {currentSlide.title}
                      </h2>
                  </div>
              </div>

              <div className="mb-6 px-2 animate-slide-up" key={`text-${slideIndex}`}>
                  <p className="text-earth-600 font-medium text-lg leading-relaxed">
                      {currentSlide.desc}
                  </p>
              </div>

              <div className="mt-auto">
                  <div className="flex gap-2 mb-6 justify-center">
                      {slides.map((_, idx) => (
                          <div 
                            key={idx} 
                            className={`h-2 rounded-full transition-all duration-300 ${idx === slideIndex ? `w-8 bg-earth-900` : 'w-2 bg-earth-200'}`}
                          />
                      ))}
                  </div>

                  <Button onClick={handleNextSlide} className="w-full py-3 text-base shadow-lg hover:translate-y-[-2px] transition-transform">
                      {slideIndex === slides.length - 1 ? 'Start Setup' : 'Next'} <ArrowRight className="w-5 h-5 ml-2"/>
                  </Button>
              </div>
          </div>
      </div>
  )
};

import React, { useState, useEffect } from 'react';
import { X, MapPin, User, Phone, Home, Briefcase, ShieldCheck, Loader2, CheckCircle2, ChevronRight, Plus } from 'lucide-react';
import { Button } from './Button';
import { Address } from '../types';

interface CheckoutAddressModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (address: Address) => void;
  existingAddresses: Address[];
}

// Mock Pincode Data
const MOCK_PINCODES: Record<string, { city: string, state: string }> = {
    '40': { city: 'Mumbai', state: 'Maharashtra' },
    '11': { city: 'New Delhi', state: 'Delhi' },
    '56': { city: 'Bengaluru', state: 'Karnataka' },
    '60': { city: 'Chennai', state: 'Tamil Nadu' },
    '70': { city: 'Kolkata', state: 'West Bengal' },
};

export const CheckoutAddressModal: React.FC<CheckoutAddressModalProps> = ({ isOpen, onClose, onConfirm, existingAddresses }) => {
  const [view, setView] = useState<'list' | 'form'>(existingAddresses.length > 0 ? 'list' : 'form');
  const [selectedId, setSelectedId] = useState<string | null>(existingAddresses.find(a => a.isDefault)?.id || (existingAddresses[0]?.id) || null);

  const [formData, setFormData] = useState<Omit<Address, 'id' | 'isDefault'>>({
    fullName: '',
    mobile: '',
    line1: '',
    line2: '',
    landmark: '',
    pincode: '',
    city: '',
    state: '',
    type: 'Home'
  });

  const [isPincodeLoading, setIsPincodeLoading] = useState(false);

  if (!isOpen) return null;

  const handlePincodeChange = (code: string) => {
    setFormData(prev => ({ ...prev, pincode: code }));
    if (code.length === 6) {
        setIsPincodeLoading(true);
        setTimeout(() => {
            const prefix = code.substring(0, 2);
            const data = MOCK_PINCODES[prefix];
            if (data) {
                setFormData(prev => ({ ...prev, city: data.city, state: data.state }));
            }
            setIsPincodeLoading(false);
        }, 400);
    }
  };

  const handleConfirm = () => {
    if (view === 'list' && selectedId) {
      const addr = existingAddresses.find(a => a.id === selectedId);
      if (addr) onConfirm(addr);
    } else {
      const newAddr: Address = {
        ...formData,
        id: `addr-${Date.now()}`,
        isDefault: existingAddresses.length === 0
      };
      onConfirm(newAddr);
    }
  };

  const isFormValid = formData.fullName && formData.mobile.length === 10 && formData.line1 && formData.pincode.length === 6 && formData.city;

  return (
    <div className="fixed inset-0 z-[70] flex items-end sm:items-center justify-center bg-earth-900/60 backdrop-blur-sm p-4 animate-fade-in-up">
      <div className="bg-white rounded-[2.5rem] w-full max-w-md max-h-[90vh] overflow-hidden shadow-2xl relative flex flex-col border-4 border-earth-100">

        {/* Header */}
        <div className="p-6 pb-4 flex justify-between items-start">
            <div>
                <h2 className="font-display font-black text-3xl text-earth-900 mb-1">Shipping Details 📦</h2>
                <p className="text-earth-700 text-sm font-bold">Where should we send your finds?</p>
            </div>
            <button onClick={onClose} className="p-2 bg-earth-50 rounded-full hover:bg-earth-100">
                <X className="w-5 h-5 text-earth-600" />
            </button>
        </div>

        <div className="px-6 pb-4">
             <div className="inline-flex items-center gap-1.5 bg-earth-50 border border-earth-100 px-2 py-1.5 rounded-lg">
                <ShieldCheck className="w-3 h-3 text-earth-700" />
                <span className="text-[10px] font-black text-earth-700 uppercase tracking-wide">Used only for pickups & deliveries</span>
            </div>
        </div>

        <div className="flex-1 overflow-y-auto no-scrollbar px-6 space-y-6 pb-6">
            {view === 'list' ? (
                <div className="space-y-4">
                    {existingAddresses.map((addr) => (
                        <div 
                            key={addr.id}
                            onClick={() => setSelectedId(addr.id)}
                            className={`p-4 rounded-2xl border-2 transition-all cursor-pointer relative ${selectedId === addr.id ? 'border-earth-900 bg-earth-50 shadow-md' : 'border-earth-100 hover:border-earth-200'}`}
                        >
                            <div className="flex justify-between items-start mb-2">
                                <div className="flex items-center gap-2">
                                    {addr.type === 'Home' ? <Home className="w-4 h-4 text-earth-700" /> : <Briefcase className="w-4 h-4 text-earth-700" />}
                                    <span className="text-[10px] font-black uppercase tracking-widest text-earth-700">{addr.type}</span>
                                </div>
                                {selectedId === addr.id && <CheckCircle2 className="w-5 h-5 text-pop-lime" />}
                            </div>
                            <h4 className="font-bold text-earth-900 text-sm">{addr.fullName}</h4>
                            <p className="text-xs text-earth-600 line-clamp-2 mt-1">{addr.line1}, {addr.city}</p>
                            <p className="text-xs text-earth-800 font-bold mt-1">{addr.mobile}</p>
                        </div>
                    ))}
                    <button 
                        onClick={() => setView('form')}
                        className="w-full py-4 rounded-2xl border-2 border-dashed border-earth-300 text-earth-600 font-bold text-sm flex items-center justify-center gap-2 hover:border-earth-900 hover:text-earth-900 transition-all"
                    >
                        <Plus className="w-4 h-4" /> Add New Address
                    </button>
                </div>
            ) : (
                <div className="space-y-6 animate-slide-in-right">
                    {existingAddresses.length > 0 && (
                        <button onClick={() => setView('list')} className="text-xs font-black text-brand-700 uppercase">← Back to saved</button>
                    )}

                    <div className="space-y-3">
                        <h4 className="text-xs font-black text-earth-900 uppercase tracking-widest flex items-center gap-2"><User className="w-3 h-3"/> Contact</h4>
                        <div className="bg-earth-50 p-1 rounded-2xl border border-earth-100">
                            <div className="relative border-b border-earth-100">
                                <User className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-earth-600" />
                                <input 
                                    value={formData.fullName}
                                    onChange={(e) => setFormData(prev => ({...prev, fullName: e.target.value}))}
                                    className="w-full bg-transparent pl-12 pr-4 py-4 font-bold text-sm text-earth-900 outline-none placeholder:text-earth-400"
                                    placeholder="Full Name"
                                />
                            </div>
                            <div className="relative">
                                <Phone className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-earth-600" />
                                <input 
                                    value={formData.mobile}
                                    onChange={(e) => setFormData(prev => ({...prev, mobile: e.target.value.replace(/\D/g, '').slice(0, 10)}))}
                                    className="w-full bg-transparent pl-12 pr-4 py-4 font-bold text-sm text-earth-900 outline-none placeholder:text-earth-400"
                                    placeholder="Mobile Number"
                                    type="tel"
                                />
                            </div>
                        </div>
                    </div>

                    <div className="space-y-3">
                        <h4 className="text-xs font-black text-earth-900 uppercase tracking-widest flex items-center gap-2"><MapPin className="w-3 h-3"/> Location</h4>
                        <div className="grid grid-cols-2 gap-3">
                            <div className="bg-earth-50 rounded-2xl px-4 py-3 border border-earth-100 relative">
                                <label className="text-[10px] font-black text-earth-800 uppercase block mb-1">Pincode</label>
                                <input 
                                    value={formData.pincode}
                                    onChange={(e) => handlePincodeChange(e.target.value.replace(/\D/g, '').slice(0, 6))}
                                    className="w-full bg-transparent font-bold text-earth-900 outline-none placeholder:text-earth-400"
                                    placeholder="000000"
                                />
                                {isPincodeLoading && <Loader2 className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 animate-spin text-earth-600"/>}
                            </div>
                            <div className="bg-earth-50 rounded-2xl px-4 py-3 border border-earth-100">
                                <label className="text-[10px] font-black text-earth-800 uppercase block mb-1">City</label>
                                <input 
                                    value={formData.city}
                                    onChange={(e) => setFormData(prev => ({...prev, city: e.target.value}))}
                                    className="w-full bg-transparent font-bold text-earth-900 outline-none placeholder:text-earth-400"
                                    placeholder="City"
                                />
                            </div>
                        </div>
                        <div className="bg-earth-50 p-4 rounded-2xl border border-earth-100 space-y-4">
                            <input 
                                value={formData.line1}
                                onChange={(e) => setFormData(prev => ({...prev, line1: e.target.value}))}
                                className="w-full bg-transparent border-b border-earth-300 pb-2 font-bold text-sm text-earth-900 outline-none placeholder:text-earth-400"
                                placeholder="Flat, House no., Building"
                            />
                            <input 
                                value={formData.line2}
                                onChange={(e) => setFormData(prev => ({...prev, line2: e.target.value}))}
                                className="w-full bg-transparent border-b border-earth-300 pb-2 font-bold text-sm text-earth-900 outline-none placeholder:text-earth-400"
                                placeholder="Area, Street, Sector"
                            />
                        </div>
                    </div>
                </div>
            )}
        </div>

        <div className="p-6 bg-white border-t border-earth-100">
            <Button 
                onClick={handleConfirm}
                className="w-full py-4 text-base shadow-xl"
                disabled={view === 'list' ? !selectedId : !isFormValid}
            >
                Confirm & Continue <ChevronRight className="w-5 h-5 ml-2" />
            </Button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Button } from './Button';
import { ArrowRight, Droplets, Truck, Users, CheckCircle2, AlertCircle, MapPin, Briefcase, Home, Loader2, User, Phone, Map, ShieldCheck } from 'lucide-react'; 
import { NeoSparkles, NeoCamera } from './NeoIcons';
import { Address } from '../types';

interface OnboardingProps {
  onComplete: (data: any) => void;
}

// Mock taken usernames for demo
const TAKEN_USERNAMES = ['admin', 'revendre', 'test', 'user', 'support', 'thrift_king'];

// Mock Pincode Data
const MOCK_PINCODES: Record<string, { city: string, state: string }> = {
    '40': { city: 'Mumbai', state: 'Maharashtra' },
    '11': { city: 'New Delhi', state: 'Delhi' },
    '56': { city: 'Bengaluru', state: 'Karnataka' },
    '60': { city: 'Chennai', state: 'Tamil Nadu' },
    '70': { city: 'Kolkata', state: 'West Bengal' },
    '50': { city: 'Hyderabad', state: 'Telangana' },
    '38': { city: 'Ahmedabad', state: 'Gujarat' },
    '30': { city: 'Jaipur', state: 'Rajasthan' },
    '41': { city: 'Pune', state: 'Maharashtra' }, 
    '20': { city: 'Noida', state: 'Uttar Pradesh' }, 
};

export const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [slideIndex, setSlideIndex] = useState(0);

  // Setup Steps: 0 = Intro Slides, 1 = Profile Basics, 2 = Address
  const [setupStep, setSetupStep] = useState(0);

  // Profile State
  const [username, setUsername] = useState('');
  const [gender, setGender] = useState<string>(''); 
  const [usernameStatus, setUsernameStatus] = useState<'idle' | 'checking' | 'available' | 'taken' | 'invalid'>('idle');
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [avatarUrl, setAvatarUrl] = useState<string>('');
  const [avatarFile, setAvatarFile] = useState<File | null>(null);

  const checkTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Address State
  const [address, setAddress] = useState({
    fullName: '',
    mobile: '',
    line1: '',
    line2: '',
    landmark: '',
    pincode: '',
    city: '',
    state: '',
    type: 'Home' as 'Home' | 'Work' | 'Other'
  });

  const [isPincodeLoading, setIsPincodeLoading] = useState(false);

  // Set default avatar based on username if not set
  useEffect(() => {
    if (!avatarFile) {
        const seed = username || 'User';
        setAvatarUrl(`https://ui-avatars.com/api/?background=E7E5E4&color=1C1917&name=${seed}&size=200&bold=true`);
    }
  }, [username, avatarFile]);

  const slides = [
    {
      id: 1,
      title: "The Revendre\nCommunity",
      desc: "Welcome to the fam! We are India's #1 social thrift marketplace. Buy, sell, and discover pre-loved fashion.",
      color: "bg-pop-yellow",
      image: "https://images.unsplash.com/photo-1523381210434-271e8be1f52b?auto=format&fit=crop&q=80&w=600",
      icon: <NeoSparkles className="w-10 h-10" />
    },
    {
      id: 2,
      title: "The Green\nRevolution",
      desc: "Every reused outfit saves water, energy, and reduces textile waste. Support a greener future.",
      color: "bg-pop-lime",
      image: "https://images.unsplash.com/photo-1542601906990-b4d3fb778b09?auto=format&fit=crop&q=80&w=600",
      icon: <Droplets className="w-10 h-10 text-earth-900" strokeWidth={2.5} />
    },
    {
      id: 3,
      title: "Creating\nLivelihoods",
      desc: "Revendre helps create jobs and steady income for small local businesses and delivery partners.",
      color: "bg-pop-cyan",
      image: "https://images.unsplash.com/photo-1556740758-90de374c12ad?auto=format&fit=crop&q=80&w=600",
      icon: <div className="flex gap-1.5"><Users className="w-6 h-6 text-earth-900"/><Truck className="w-6 h-6 text-earth-900"/></div>
    }
  ];

  const handleNextSlide = () => {
    if (slideIndex < slides.length - 1) {
      setSlideIndex(slideIndex + 1);
    } else {
      setSetupStep(1); 
    }
  };

  const handleSkip = () => {
    setSetupStep(1); 
  };

  const handleUsernameChange = (val: string) => {
    const cleanVal = val.toLowerCase().replace(/[^a-z0-9_]/g, '');
    setUsername(cleanVal);

    if (checkTimeoutRef.current) clearTimeout(checkTimeoutRef.current);

    if (cleanVal.length < 3) {
      setUsernameStatus(cleanVal.length === 0 ? 'idle' : 'invalid');
      setSuggestions([]);
      return;
    }

    setUsernameStatus('checking');

    checkTimeoutRef.current = setTimeout(() => {
      if (TAKEN_USERNAMES.includes(cleanVal)) {
        setUsernameStatus('taken');
        setSuggestions([
            `${cleanVal}_thrifter`,
            `real_${cleanVal}`,
            `${cleanVal}${Math.floor(Math.random() * 99)}`
        ]);
      } else {
        setUsernameStatus('available');
        setSuggestions([]);
      }
    }, 200); 
  };

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setAvatarFile(file);
      setAvatarUrl(URL.createObjectURL(file));
    }
  };

  const handleProfileSubmit = () => {
    if (usernameStatus !== 'available' || !gender) return;
    setSetupStep(2); 
  };

  const handlePincodeChange = (code: string) => {
      setAddress(prev => ({ ...prev, pincode: code }));

      if (code.length === 6) {
          setIsPincodeLoading(true);
          setTimeout(() => {
              const prefix = code.substring(0, 2);
              const data = MOCK_PINCODES[prefix];
              if (data) {
                  setAddress(prev => ({ ...prev, city: data.city, state: data.state }));
              }
              setIsPincodeLoading(false);
          }, 300); 
      }
  };

  const handleAddressChange = (field: string, value: string) => {
    setAddress(prev => ({ ...prev, [field]: value }));
  };

  const handleFinalSubmit = () => {
    if (!address.fullName || address.mobile.length !== 10 || !address.line1 || address.pincode.length !== 6 || !address.city) return;

    const finalAddress: Address = {
        id: `addr-${Date.now()}`,
        ...address,
        isDefault: true
    };

    const userData = {
        username,
        gender,
        displayName: address.fullName || username,
        avatarUrl, 
        addresses: [finalAddress],
        city: address.city
    };

    onComplete(userData);
  };

  const handleSkipAddress = () => {
    const userData = {
        username,
        gender,
        displayName: username,
        avatarUrl, 
        addresses: [],
        city: ''
    };
    onComplete(userData);
  };

  if (setupStep === 1) {
      return (
          <div className="min-h-screen bg-[#FAFAF9] flex flex-col items-center justify-center p-6 animate-fade-in-up">
              <div className="w-full max-w-md bg-white rounded-[2.5rem] shadow-xl p-8 border border-earth-100 relative overflow-hidden">
                  <div className="absolute top-0 right-0 w-32 h-32 bg-pop-yellow/20 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none"></div>

                  <div className="relative z-10">
                      <div className="text-center mb-8">
                          <h2 className="font-display font-black text-3xl text-earth-900 mb-2">Create Profile ✨</h2>
                          <p className="text-earth-600 text-sm font-bold">Let's get you set up.</p>
                      </div>

                      <div className="flex flex-col items-center mb-8">
                          <div className="relative group cursor-pointer">
                              <div className="w-32 h-32 rounded-full border-4 border-white shadow-xl overflow-hidden bg-earth-100 relative z-10">
                                  <img src={avatarUrl} className="w-full h-full object-cover" alt="Profile" decoding="async" />
                              </div>
                              <label className="absolute inset-0 bg-black/40 rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer z-20">
                                  <NeoCamera className="w-8 h-8 text-white" />
                                  <input type="file" className="hidden" accept="image/*" onChange={handleImageSelect} />
                              </label>
                              <div className="absolute bottom-1 right-1 bg-earth-900 p-2.5 rounded-full border-4 border-white shadow-md pointer-events-none z-30">
                                  <NeoCamera className="w-4 h-4 text-white" />
                              </div>
                          </div>
                          <p className="text-[10px] text-earth-600 font-black uppercase tracking-wide mt-3">Upload Picture (Optional)</p>
                      </div>

                      <div className="space-y-6 mb-8">
                          <div>
                              <label className="block text-xs font-black text-earth-900 uppercase tracking-wide mb-1 ml-1">Username <span className="text-pop-rose">*</span></label>
                              <div className={`relative flex items-center bg-earth-50 border-2 rounded-2xl transition-all ${
                                  usernameStatus === 'taken' ? 'border-pop-rose' : 
                                  usernameStatus === 'available' ? 'border-pop-lime' : 
                                  'border-transparent focus-within:border-earth-900 focus-within:bg-white'
                              }`}>
                                  <span className="pl-4 text-earth-500 font-bold text-lg">@</span>
                                  <input 
                                      value={username}
                                      onChange={(e) => handleUsernameChange(e.target.value)}
                                      className="w-full bg-transparent py-4 pl-1 pr-12 font-black text-lg text-earth-900 outline-none placeholder:text-earth-400"
                                      placeholder="thrift_king"
                                      autoFocus
                                  />
                                  <div className="absolute right-4">
                                      {usernameStatus === 'checking' && <Loader2 className="w-5 h-5 text-earth-600 animate-spin" />}
                                      {usernameStatus === 'available' && <CheckCircle2 className="w-6 h-6 text-pop-lime fill-earth-50" />}
                                      {usernameStatus === 'taken' && <AlertCircle className="w-6 h-6 text-pop-rose fill-earth-50" />}
                                  </div>
                              </div>

                              {usernameStatus === 'taken' && (
                                  <div className="mt-3 animate-slide-up bg-pop-rose/5 p-3 rounded-xl border border-pop-rose/10">
                                      <p className="text-xs text-pop-rose font-black mb-2">Username taken. Try these:</p>
                                      <div className="flex flex-wrap gap-2">
                                          {suggestions.map(s => (
                                              <button 
                                                key={s} 
                                                onClick={() => handleUsernameChange(s)}
                                                className="text-[10px] bg-white border border-pop-rose/20 px-3 py-1.5 rounded-lg font-black text-pop-rose hover:bg-pop-rose hover:text-white transition-colors shadow-sm"
                                              >
                                                  @{s}
                                              </button>
                                          ))}
                                      </div>
                                  </div>
                              )}
                          </div>

                          <div>
                              <label className="block text-xs font-black text-earth-900 uppercase tracking-wide mb-2 ml-1">Gender <span className="text-pop-rose">*</span></label>
                              <div className="grid grid-cols-2 gap-3">
                                  {['Men', 'Women', 'Non-binary', 'Not interested'].map((opt) => (
                                      <button
                                          key={opt}
                                          onClick={() => setGender(opt)}
                                          className={`py-3.5 px-4 rounded-2xl text-sm font-black transition-all border-2 flex items-center justify-center ${
                                              gender === opt 
                                              ? 'bg-earth-900 text-white border-earth-900 shadow-lg scale-[1.02]' 
                                              : 'bg-white text-earth-600 border-earth-100 hover:border-earth-300 active:scale-95'
                                          }`}
                                      >
                                          {opt}
                                      </button>
                                  ))}
                              </div>
                          </div>
                      </div>

                      <Button 
                        onClick={handleProfileSubmit} 
                        className="w-full py-3 text-base shadow-lg"
                        disabled={usernameStatus !== 'available' || !gender}
                      >
                          Next: Address <ArrowRight className="w-5 h-5 ml-2"/>
                      </Button>
