    }
  };

  const handleSave = async () => {
    if (!username.trim()) {
      setError("Username is required.");
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      let finalAvatarUrl = currentUser.avatarUrl;

      if (avatarFile) {
        try {
          const storageRef = storage.ref(`avatars/${currentUser.id}/${Date.now()}_${avatarFile.name}`);
          await storageRef.put(avatarFile);
          finalAvatarUrl = await storageRef.getDownloadURL();
        } catch (uploadError) {
          finalAvatarUrl = avatarPreview; 
        }
      }

      // Update the first address in the array
      const updatedAddresses = currentUser.addresses ? [...currentUser.addresses] : [];
      if (updatedAddresses.length > 0) {
          updatedAddresses[0] = { ...address, id: updatedAddresses[0].id, isDefault: true };
      } else {
          updatedAddresses.push({ ...address, id: `addr-${Date.now()}`, isDefault: true });
      }

      await onUpdateUser({
        displayName,
        username,
        bio,
        avatarUrl: finalAvatarUrl,
        addresses: updatedAddresses,
        city: address.city // Keep legacy city field in sync
      });

      onClose();
    } catch (err) {
      console.error("Failed to update profile", err);
      setError("Failed to save changes. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-earth-900/60 backdrop-blur-sm p-4 animate-fade-in-up">
      <div className="bg-white rounded-[2.5rem] w-full max-w-md shadow-2xl relative overflow-hidden flex flex-col max-h-[90vh]">
        {/* Header */}
        <div className="px-8 py-6 border-b border-earth-100 flex items-center justify-between bg-white sticky top-0 z-10">
          <h2 className="font-display font-black text-2xl text-earth-900">Edit Profile</h2>
          <button onClick={onClose} className="p-2 bg-earth-50 rounded-full hover:bg-earth-100 transition-colors">
            <X className="w-5 h-5 text-earth-900" />
          </button>
        </div>

        <div className="p-8 overflow-y-auto no-scrollbar flex-1 space-y-8">
          {/* Avatar Section */}
          <div className="flex flex-col items-center">
            <div className="relative group cursor-pointer">
              <div className="w-32 h-32 rounded-full border-4 border-white shadow-xl overflow-hidden bg-earth-100">
                <img src={avatarPreview} className="w-full h-full object-cover" alt="Avatar" />
              </div>
              <label className="absolute inset-0 bg-black/40 rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer">
                <NeoCamera className="w-8 h-8 text-white" />
                <input type="file" className="hidden" accept="image/*" onChange={handleImageSelect} />
              </label>
              <div className="absolute bottom-1 right-1 bg-earth-900 p-2.5 rounded-full border-4 border-white shadow-md">
                 <NeoCamera className="w-4 h-4 text-white" />
              </div>
            </div>
            <p className="text-[10px] font-black text-earth-500 mt-3 uppercase tracking-widest">Change Profile Photo</p>
          </div>

          {/* Account Basics */}
          <div className="space-y-5">
            <h3 className="text-xs font-black text-earth-900 uppercase tracking-widest flex items-center gap-2 mb-4">
                <UserIcon className="w-4 h-4"/> Account Basics
            </h3>

            <div>
                <label className="block text-[10px] font-black text-earth-900 uppercase tracking-wide mb-2 ml-1">Username</label>
                <div className="flex items-center bg-earth-50 rounded-2xl px-4 border-2 border-transparent focus-within:border-earth-900 focus-within:bg-white transition-all">
                    <span className="text-earth-400 font-bold text-lg">@</span>
                    <input 
                        value={username}
                        onChange={(e) => setUsername(e.target.value)}
                        className="w-full bg-transparent py-4 pl-1 font-black text-base outline-none text-earth-900"
                        placeholder="username"
                    />
                </div>
            </div>

            <div>
                <label className="block text-[10px] font-black text-earth-900 uppercase tracking-wide mb-2 ml-1">Display Name</label>
                <input 
                    value={displayName}
                    onChange={(e) => setDisplayName(e.target.value)}
                    className="w-full bg-earth-50 rounded-2xl px-5 py-4 font-black text-base outline-none border-2 border-transparent focus:border-earth-900 focus:bg-white transition-all text-earth-900"
                    placeholder="Your Name"
                />
            </div>

            <div>
                <label className="block text-[10px] font-black text-earth-900 uppercase tracking-wide mb-2 ml-1">Bio</label>
                <textarea 
                    value={bio}
                    onChange={(e) => setBio(e.target.value)}
                    className="w-full bg-earth-50 rounded-2xl px-5 py-4 font-bold text-sm outline-none border-2 border-transparent focus:border-earth-900 focus:bg-white transition-all text-earth-900 h-24 resize-none"
                    placeholder="Tell us about your style..."
                    maxLength={150}
                />
                <div className="text-right text-[10px] text-earth-400 font-black mt-1 uppercase">{bio.length}/150</div>
            </div>
          </div>

          {/* Shipping Details Section */}
          <div className="space-y-6 pt-4">
              <div className="flex items-center justify-between">
                <h3 className="text-xs font-black text-earth-900 uppercase tracking-widest flex items-center gap-2">
                    <ShieldCheck className="w-4 h-4 text-pop-cyan"/> Shipping Details
                </h3>
                <div className="bg-earth-100 px-2 py-1 rounded text-[8px] font-black text-earth-500 uppercase tracking-tighter">Verified for Deliveries</div>
              </div>

              <div className="space-y-4">
                  <h4 className="text-[10px] font-black text-earth-900 uppercase tracking-widest mb-1 ml-1 flex items-center gap-2 opacity-60">Contact Information</h4>
                  <div className="bg-earth-50 p-1 rounded-2xl border-2 border-earth-100">
                      <div className="relative border-b-2 border-earth-100">
                          <UserIcon className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-earth-900" />
                          <input 
                              value={address.fullName}
                              onChange={(e) => setAddress(prev => ({...prev, fullName: e.target.value}))}
                              className="w-full bg-transparent pl-12 pr-4 py-4 font-black text-sm text-earth-900 outline-none placeholder:text-earth-400 placeholder:font-bold"
                              placeholder="Receiver's Full Name"
                          />
                      </div>
                      <div className="relative">
                          <Phone className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-earth-900" />
                          <input 
                              value={address.mobile}
                              onChange={(e) => setAddress(prev => ({...prev, mobile: e.target.value.replace(/\D/g, '').slice(0, 10)}))}
                              className="w-full bg-transparent pl-12 pr-4 py-4 font-black text-sm text-earth-900 outline-none placeholder:text-earth-400 placeholder:font-bold"
                              placeholder="10-digit Mobile Number"
                              type="tel"
                          />
                      </div>
                  </div>
              </div>

              <div className="space-y-4">
                  <h4 className="text-[10px] font-black text-earth-900 uppercase tracking-widest mb-1 ml-1 flex items-center gap-2 opacity-60">Address & Location</h4>
                  <div className="grid grid-cols-2 gap-3">
                      <div className="bg-earth-50 rounded-2xl px-5 py-4 border-2 border-earth-100 relative focus-within:border-earth-900 focus-within:bg-white transition-all">
