  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (isOpen) {
      setError(null);
      setAddress(currentUser.addresses?.[0] || defaultAddress);
    }
  }, [isOpen, currentUser]);

  if (!isOpen) return null;

  const handlePincodeChange = (code: string) => {
    setAddress(prev => ({ ...prev, pincode: code }));
    if (code.length === 6) {
        setIsPincodeLoading(true);
        setTimeout(() => {
            const prefix = code.substring(0, 2);
            const data = MOCK_PINCODES[prefix];
            if (data) {
                setAddress(prev => ({ ...prev, city: data.city, state: data.state }));
            }
            setIsPincodeLoading(false);
        }, 400);
    }
  };

  const handleSave = async () => {
    setIsLoading(true);
    setError(null);

    try {
      // Update the first address in the array
      const updatedAddresses = currentUser.addresses ? [...currentUser.addresses] : [];
      if (updatedAddresses.length > 0) {
          updatedAddresses[0] = { ...address, id: updatedAddresses[0].id, isDefault: true };
      } else {
          updatedAddresses.push({ ...address, id: `addr-${Date.now()}`, isDefault: true });
      }

      await onUpdateUser({
        addresses: updatedAddresses,
        city: address.city // Keep legacy city field in sync
      });

      onClose();
    } catch (err) {
      console.error("Failed to update shipping details", err);
      setError("Failed to save changes. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-earth-900/60 backdrop-blur-sm p-4 animate-fade-in-up">
      <div className="bg-white rounded-[2.5rem] w-full max-w-md shadow-2xl relative overflow-hidden flex flex-col max-h-[90vh]">
        {/* Header - Simple & Clean */}
        <div className="px-8 py-6 border-b border-earth-100 flex items-center justify-between bg-white sticky top-0 z-10">
          <h2 className="font-display font-black text-2xl text-earth-900">Shipping Details</h2>
          <button onClick={onClose} className="p-2 bg-earth-50 rounded-full hover:bg-earth-100 transition-colors">
            <X className="w-5 h-5 text-earth-900" />
          </button>
        </div>

        <div className="p-8 overflow-y-auto no-scrollbar flex-1 space-y-8">
          {/* Managed Address Section */}
          <div className="space-y-6">
              <div className="flex items-center justify-between mb-2">
                <h3 className="text-xs font-black text-earth-900 uppercase tracking-widest flex items-center gap-2">
                    <ShieldCheck className="w-4 h-4 text-pop-cyan"/> Primary Address
                </h3>
                <div className="bg-earth-100 px-2 py-1 rounded text-[8px] font-black text-earth-500 uppercase tracking-tighter">Verified for Deliveries</div>
              </div>

              {/* Contact Information */}
              <div className="space-y-4">
                  <h4 className="text-[10px] font-black text-earth-900 uppercase tracking-widest opacity-60 ml-1">Contact Information</h4>
                  <div className="bg-earth-50 p-1 rounded-2xl border-2 border-earth-100">
                      <div className="relative border-b-2 border-earth-100">
                          <UserIcon className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-earth-900" />
                          <input 
                              value={address.fullName}
                              onChange={(e) => setAddress(prev => ({...prev, fullName: e.target.value}))}
                              className="w-full bg-transparent pl-12 pr-4 py-4 font-black text-sm text-earth-900 outline-none placeholder:text-earth-400 placeholder:font-bold"
                              placeholder="Receiver's Full Name"
                          />
                      </div>
                      <div className="relative">
                          <Phone className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-earth-900" />
                          <input 
                              value={address.mobile}
                              onChange={(e) => setAddress(prev => ({...prev, mobile: e.target.value.replace(/\D/g, '').slice(0, 10)}))}
                              className="w-full bg-transparent pl-12 pr-4 py-4 font-black text-sm text-earth-900 outline-none placeholder:text-earth-400 placeholder:font-bold"
                              placeholder="10-digit Mobile Number"
                              type="tel"
                          />
                      </div>
                  </div>
              </div>

              {/* Address & Location */}
              <div className="space-y-4">
                  <h4 className="text-[10px] font-black text-earth-900 uppercase tracking-widest opacity-60 ml-1">Address & Location</h4>
                  <div className="grid grid-cols-2 gap-3">
                      <div className="bg-earth-50 rounded-2xl px-5 py-4 border-2 border-earth-100 relative focus-within:border-earth-900 focus-within:bg-white transition-all">
                          <label className="text-[10px] font-black text-earth-900 uppercase block mb-1">Pincode</label>
                          <input 
                              value={address.pincode}
                              onChange={(e) => handlePincodeChange(e.target.value.replace(/\D/g, '').slice(0, 6))}
                              className="w-full bg-transparent font-black text-base text-earth-900 outline-none"
                              placeholder="000000"
                          />
                          {isPincodeLoading && <Loader2 className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 animate-spin text-earth-900"/>}
                      </div>
                      <div className="bg-earth-50 rounded-2xl px-5 py-4 border-2 border-earth-100 focus-within:border-earth-900 focus-within:bg-white transition-all">
                          <label className="text-[10px] font-black text-earth-900 uppercase block mb-1">City</label>
                          <input 
                              value={address.city}
                              onChange={(e) => setAddress(prev => ({...prev, city: e.target.value}))}
                              className="w-full bg-transparent font-black text-base text-earth-900 outline-none placeholder:text-earth-400"
                              placeholder="City"
                          />
                      </div>
                  </div>

                  <div className="bg-earth-50 p-5 rounded-2xl border-2 border-earth-100 space-y-5 focus-within:bg-white transition-all">
                      <input 
                          value={address.line1}
                          onChange={(e) => setAddress(prev => ({...prev, line1: e.target.value}))}
                          className="w-full bg-transparent border-b-2 border-earth-100 pb-3 font-black text-sm text-earth-900 outline-none focus:border-earth-900"
                          placeholder="Flat, House no., Building, Apartment"
                      />
                      <input 
                          value={address.line2}
                          onChange={(e) => setAddress(prev => ({...prev, line2: e.target.value}))}
                          className="w-full bg-transparent border-b-2 border-earth-100 pb-3 font-black text-sm text-earth-900 outline-none focus:border-earth-900"
                          placeholder="Area, Street, Sector, Village"
                      />
                      <div className="grid grid-cols-2 gap-4">
                          <input 
                              value={address.landmark}
                              onChange={(e) => setAddress(prev => ({...prev, landmark: e.target.value}))}
                              className="w-full bg-transparent font-black text-sm text-earth-900 outline-none placeholder:text-earth-400"
                              placeholder="Landmark (Optional)"
                          />
                          <input 
                              value={address.state}
                              onChange={(e) => setAddress(prev => ({...prev, state: e.target.value}))}
                              className="w-full bg-transparent font-black text-sm text-earth-900 outline-none text-right placeholder:text-earth-400"
                              placeholder="State"
                          />
                      </div>
                  </div>
              </div>

              {/* Address Label */}
              <div className="space-y-4">
                  <h4 className="text-[10px] font-black text-earth-900 uppercase tracking-widest opacity-60 ml-1">Label Address As</h4>
                  <div className="bg-earth-50 p-1.5 rounded-2xl flex gap-2 border-2 border-earth-100">
                      {[
                          { id: 'Home', icon: Home }, 
                          { id: 'Work', icon: Briefcase }, 
                          { id: 'Other', icon: MapPin }
                      ].map((t) => (
                          <button
                              key={t.id}
                              onClick={() => setAddress(prev => ({...prev, type: t.id as any}))}
                              className={`flex-1 py-3 rounded-xl text-xs font-black transition-all flex items-center justify-center gap-2 ${
                                  address.type === t.id 
                                  ? 'bg-earth-900 text-white shadow-xl scale-100' 
                                  : 'text-earth-600 hover:text-earth-900'
                              }`}
                          >
                              <t.icon className="w-4 h-4" /> {t.id}
                          </button>
                      ))}
                  </div>
              </div>
          </div>

          {error && (
            <div className="mt-4 bg-pop-rose/10 border-2 border-pop-rose/20 p-4 rounded-2xl flex gap-3 items-start animate-bounce-in">
                <AlertTriangle className="w-5 h-5 text-pop-rose shrink-0" />
                <p className="text-xs font-black text-pop-rose">{error}</p>
            </div>
          )}
        </div>

        {/* Action Footer */}
        <div className="p-8 bg-white border-t border-earth-100 flex flex-col gap-3">
            <Button onClick={handleSave} className="w-full py-4 text-lg bg-earth-900 text-white shadow-[0_10px_30px_rgba(0,0,0,0.15)] rounded-2xl" disabled={isLoading}>
                {isLoading ? (
                    <span className="flex items-center gap-2">Saving... <Loader2 className="w-5 h-5 animate-spin"/></span>
                ) : (
                    <span className="flex items-center gap-2 font-black">Update Address <Save className="w-5 h-5 ml-1" /></span>
                )}
            </Button>
            <p className="text-[10px] text-center font-black text-earth-400 uppercase tracking-widest">Updates are synced instantly</p>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { User, Post } from '../types';
import { Settings, Grid, BarChart2, Truck, Share2, Bookmark, MapPin, Package } from 'lucide-react';
import { NeoStar } from './NeoIcons';

interface ProfileProps {
  user: User;
  posts: Post[];
  savedPosts?: Post[]; 
  onOpenDashboard?: () => void;
  onOpenOrderTracking?: () => void;
  onOpenSettings?: () => void;
  onPostClick?: (post: Post) => void;
}

export const Profile: React.FC<ProfileProps> = ({ user, posts, savedPosts = [], onOpenDashboard, onOpenOrderTracking, onOpenSettings, onPostClick }) => {
  const [activeTab, setActiveTab] = useState<'closet' | 'saved'>('closet');
  const userPosts = posts.filter(p => p.user.id === user.id);
  const displayPosts = activeTab === 'closet' ? userPosts : savedPosts;

  return (
    <div className="bg-[#F0F0F0] min-h-full pb-32 animate-fade-in-up">
      <div className="h-40 bg-earth-900 relative overflow-hidden">
          <div className="absolute inset-0 opacity-20 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]"></div>
          <div className="absolute top-4 right-4 flex gap-2">
              <button className="bg-white/20 backdrop-blur-md p-2 rounded-full hover:bg-white/30 text-white transition-colors"><Share2 className="w-5 h-5"/></button>
              <button 
                onClick={onOpenSettings}
                className="bg-white/20 backdrop-blur-md p-2 rounded-full hover:bg-white/30 text-white transition-colors"
              >
                  <Settings className="w-5 h-5"/>
              </button>
          </div>
      </div>

      <div className="px-6 -mt-16 relative z-10">
          <div className="bg-white p-6 rounded-[2.5rem] shadow-xl text-center">
              <div className="relative inline-block mb-4">
                  <div className="w-24 h-24 rounded-full p-1 bg-white mx-auto shadow-lg">
                      <img src={user.avatarUrl} className="w-full h-full rounded-full object-cover" alt="" />
                  </div>
                  <div className="absolute bottom-0 right-0 bg-pop-yellow text-earth-900 text-[10px] font-black px-2 py-1 rounded-lg flex items-center gap-1 shadow-sm">
                      <NeoStar className="w-3 h-3" /> {user.sellerRating || 0}
                  </div>
              </div>

              <h2 className="font-display font-black text-2xl text-earth-900 mb-1">{user.displayName || user.username}</h2>
              <p className="text-earth-500 text-sm font-bold mb-4">{user.bio || 'No bio yet.'}</p>

              <div className="flex justify-center items-center gap-6 py-4 border-t border-earth-100 mb-4 border-dashed">
                  <div className="text-center">
                      <div className="font-black text-xl text-earth-900">{user.totalSales}</div>
                      <div className="text-[10px] uppercase font-black text-earth-400 tracking-wide">Sold</div>
                  </div>
                  <div className="text-center">
                      <div className="font-black text-xl text-earth-900">0</div>
                      <div className="text-[10px] uppercase font-black text-earth-400 tracking-wide">Follows</div>
                  </div>
                  <div className="text-center">
                      <div className="font-black text-xl text-earth-900">{userPosts.length}</div>
                      <div className="text-[10px] uppercase font-black text-earth-400 tracking-wide">Posted</div>
                  </div>
              </div>

              <div className="space-y-3">
                  <div className="grid grid-cols-2 gap-3">
                      {onOpenDashboard && (
                          <button onClick={onOpenDashboard} className="bg-earth-900 text-white py-3 rounded-xl font-bold text-sm shadow-lg hover:bg-earth-800 active:scale-95 transition-all flex items-center justify-center gap-2">
                              <BarChart2 className="w-4 h-4"/> Dashboard
                          </button>
                      )}
                      {onOpenOrderTracking && (
                          <button onClick={onOpenOrderTracking} className="bg-earth-50 text-earth-900 py-3 rounded-xl font-bold text-sm hover:bg-earth-100 active:scale-95 transition-all flex items-center justify-center gap-2">
                              <Truck className="w-4 h-4"/> Orders
                          </button>
                      )}
                  </div>
              </div>
          </div>
      </div>

      {/* Account Quick Actions Grid */}
      <div className="px-6 mt-8">
          <div className="grid grid-cols-2 gap-4">
              <button 
                onClick={onOpenOrderTracking}
                className="bg-white p-6 rounded-[2rem] border border-earth-200 shadow-sm hover:shadow-md hover:border-earth-300 transition-all active:scale-95 flex flex-col items-center justify-center gap-2 group"
              >
                  <Package className="w-6 h-6 text-earth-400 group-hover:text-earth-900 transition-colors" />
                  <span className="font-black text-earth-900 text-sm tracking-tight">Your Orders</span>
              </button>
              <button 
                onClick={onOpenSettings}
                className="bg-white p-6 rounded-[2rem] border border-earth-200 shadow-sm hover:shadow-md hover:border-earth-300 transition-all active:scale-95 flex flex-col items-center justify-center gap-2 group"
              >
                  <MapPin className="w-6 h-6 text-earth-400 group-hover:text-earth-900 transition-colors" />
                  <span className="font-black text-earth-900 text-sm tracking-tight">Your Addresses</span>
              </button>
          </div>
      </div>

      <div className="px-6 mt-10">
          <div className="flex items-center gap-6 mb-4 border-b border-earth-200">
              <button 
                onClick={() => setActiveTab('closet')}
                className={`flex items-center gap-2 pb-3 font-display font-bold text-lg transition-colors relative ${activeTab === 'closet' ? 'text-earth-900' : 'text-earth-400'}`}
              >
                  <Grid className="w-5 h-5" /> Closet
                  {activeTab === 'closet' && <span className="absolute bottom-0 left-0 right-0 h-1 bg-pop-cyan rounded-t-full"></span>}
              </button>
              <button 
                onClick={() => setActiveTab('saved')}
                className={`flex items-center gap-2 pb-3 font-display font-bold text-lg transition-colors relative ${activeTab === 'saved' ? 'text-earth-900' : 'text-earth-400'}`}
              >
                  <Bookmark className="w-5 h-5" /> Saved
                  {activeTab === 'saved' && <span className="absolute bottom-0 left-0 right-0 h-1 bg-pop-purple rounded-t-full"></span>}
              </button>
          </div>

          {displayPosts.length === 0 ? (
              <div className="text-center py-12 bg-white rounded-[2rem] border-2 border-earth-100 border-dashed animate-fade-in-up">
                  <div className="w-12 h-12 bg-earth-50 rounded-full flex items-center justify-center mx-auto mb-3">
                      <Grid className="w-6 h-6 text-earth-300"/>
                  </div>
                  <p className="text-earth-400 text-sm font-bold">{activeTab === 'closet' ? 'Closet is empty.' : 'No saved items.'}</p>
                  <p className="text-earth-300 text-xs mt-1">{activeTab === 'closet' ? 'Upload your first fit!' : 'Bookmark items to save them.'}</p>
              </div>
          ) : (
              <div className="columns-2 gap-4 space-y-4">
                  {displayPosts.map((post, idx) => (
                      <div 
                        key={idx} 
                        onClick={() => onPostClick && onPostClick(post)}
                        className="break-inside-avoid relative rounded-2xl overflow-hidden group cursor-pointer shadow-md hover:shadow-xl transition-all duration-300"
                      >
                          <img src={post.imageUrl} className="w-full object-cover group-hover:scale-110 transition-transform duration-500" alt="" />
                          {post.isSold && (
                              <div className="absolute inset-0 bg-black/50 flex items-center justify-center">
                                  <span className="bg-white text-earth-900 text-xs font-black px-3 py-1 rounded uppercase tracking-widest -rotate-6 shadow-lg">Sold</span>
                              </div>
                          )}
                          <div className="absolute bottom-2 left-2 right-2 bg-white/90 backdrop-blur px-2 py-1 rounded-lg text-xs font-black shadow-sm text-earth-900 truncate">
                              ₹{post.price}
                          </div>
                      </div>
                  ))}
              </div>
          )}
      </div>
    </div>
  );
};
